"""Insight Daemon orchestrator — runs detectors, deduplicates, writes insights."""

from __future__ import annotations

import hashlib
import sqlite3
import time
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from sqlite3 import Connection

from cerebrofy.memory.store import write_memory, Memory
from cerebrofy.embedder import get_embedder


@dataclass(frozen=True, slots=True)
class Insight:
    """A proactive insight generated by the daemon."""

    type: str
    title: str
    body: str
    confidence: float
    affected_neurons: list[str]
    affected_lobes: list[str]
    recommendation: str
    created_ts: int


def run_daemon(db_path: str | Path) -> list[Insight]:
    """Run all insight detectors against the database and write new insights."""
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row

    try:
        detectors = [
            TrendAlertDetector(),
            SessionPatternDetector(),
            SiloRiskDetector(),
            ArchPredictionDetector(),
            MemoryConflictDetector(),
            CoverageRegressionDetector(),
            AgentDriftDetector(),
            ArchViolationPredictionDetector(),
        ]

        all_insights: list[Insight] = []
        for detector in detectors:
            all_insights.extend(detector.detect(conn))

        existing = _load_recent_insight_hashes(conn, window_hours=24)
        new_insights = [i for i in all_insights if _insight_hash(i) not in existing]

        embedder = get_embedder("default")
        if embedder is None:
            raise RuntimeError("Embedder not available")
        for insight in new_insights:
            memory = Memory(
                id=_insight_id(insight),
                neuron_id=None,
                lobe=None,
                type="insight",
                title=insight.title,
                body=insight.body,
                author="cerebrofy-insight-daemon",
                created_ts=insight.created_ts,
                tags=(f"insight,{insight.type}",),
                decay_score=1.0,
                status="active",
            )
            write_memory(conn=conn, memory=memory, embedding=embedder.embed([insight.title + " " + insight.body])[0])

        return new_insights
    finally:
        conn.close()


def _insight_hash(insight: Insight) -> str:
    """Hash of title for deduplication."""
    return hashlib.sha256(insight.title.encode()).hexdigest()[:16]


def _insight_id(insight: Insight) -> str:
    """Generate a unique ID for an insight."""
    base = f"insight-{insight.type}-{insight.created_ts}"
    return hashlib.sha256(base.encode()).hexdigest()[:24]


def _load_recent_insight_hashes(conn: Connection, window_hours: int = 24) -> set[str]:
    """Load hashes of recent insight titles to prevent re-firing."""
    cutoff = int(time.time()) - window_hours * 3600
    rows = conn.execute(
        "SELECT title FROM memories WHERE type = 'insight' AND created_ts >= ?",
        (cutoff,),
    ).fetchall()
    return {hashlib.sha256(row["title"].encode()).hexdigest()[:16] for row in rows}


class BaseDetector:
    """Base class for insight detectors."""

    def detect(self, conn: Connection) -> list[Insight]:
        raise NotImplementedError


class TrendAlertDetector(BaseDetector):
    """Detect health metric drift over consecutive builds."""

    def detect(self, conn: Connection) -> list[Insight]:
        insights: list[Insight] = []
        rows = conn.execute(
            """
            SELECT build_ts, coupling, avg_blast, dead_code_pct, test_surface, hub_concentration
            FROM health_snapshots
            ORDER BY build_ts DESC
            LIMIT 5
            """
        ).fetchall()

        if len(rows) < 3:
            return insights

        # Check coupling drift
        recent_coupling = [r["coupling"] for r in rows[:3]]
        if all(r2 > r1 for r1, r2 in zip(recent_coupling, recent_coupling[1:])):
            drift_pct = ((recent_coupling[0] - recent_coupling[-1]) / recent_coupling[-1]) * 100
            if drift_pct >= 15:
                insights.append(
                    Insight(
                        type="trend_alert",
                        title=f"Coupling score drifting up {drift_pct:.0f}% over {len(rows)} builds",
                        body=f"Coupling increased from {recent_coupling[-1]:.3f} to {recent_coupling[0]:.3f} over the last {len(rows)} builds. Cross-lobe dependencies are growing.",
                        confidence=min(drift_pct / 25, 1.0),
                        affected_neurons=[],
                        affected_lobes=[],
                        recommendation="Review new cross-lobe edges; consider refactoring to reduce coupling.",
                        created_ts=int(time.time()),
                    )
                )

        # Check test surface regression
        recent_test = [r["test_surface"] for r in rows[:3]]
        if len(recent_test) >= 3 and recent_test[0] < recent_test[-1] * 0.95:
            drop_pct = ((recent_test[-1] - recent_test[0]) / recent_test[-1]) * 100
            insights.append(
                Insight(
                    type="coverage_regression",
                    title=f"Test surface dropped {drop_pct:.0f}% over {len(rows)} builds",
                    body=f"Test surface decreased from {recent_test[-1]:.1f}% to {recent_test[0]:.1f}%. New code may lack test coverage.",
                    confidence=min(drop_pct / 20, 1.0),
                    affected_neurons=[],
                    affected_lobes=[],
                    recommendation="Run cerebrofy_coverage_gap to identify untested neurons; add tests for recent changes.",
                    created_ts=int(time.time()),
                )
            )

        return insights


class SessionPatternDetector(BaseDetector):
    """Detect session failure patterns by lobe."""

    def detect(self, conn: Connection) -> list[Insight]:
        insights: list[Insight] = []

        # Check if sessions table exists
        tables = {r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        if "sessions" not in tables or "session_events" not in tables:
            return insights

        rows = conn.execute(
            """
            SELECT lobe, COUNT(*) as total, SUM(CASE WHEN outcome='failed' THEN 1 ELSE 0 END) as failed
            FROM (
                SELECT se.session_id,
                       CASE
                           WHEN n.lobe IS NOT NULL THEN n.lobe
                           ELSE 'unknown'
                       END as lobe,
                       s.outcome
                FROM session_events se
                JOIN sessions s ON se.session_id = s.id
                LEFT JOIN nodes n ON se.tool = 'cerebrofy_impact' AND se.args LIKE '%' || n.id || '%'
                WHERE s.outcome IN ('success', 'failed')
            )
            GROUP BY lobe
            HAVING total >= 5
            """
        ).fetchall()

        for row in rows:
            total = row["total"]
            failed = row["failed"] or 0
            if total > 0 and failed / total > 0.5:
                insights.append(
                    Insight(
                        type="session_pattern",
                        title=f"Sessions touching {row['lobe']}/ fail {failed/total*100:.0f}% of the time",
                        body=f"Analyzed {total} sessions involving {row['lobe']}/. {failed} failed ({failed/total*100:.0f}% failure rate).",
                        confidence=min(failed / total * 1.5, 1.0),
                        affected_neurons=[],
                        affected_lobes=[row["lobe"]],
                        recommendation="Investigate common failure patterns in this lobe; consider stricter pre-commit checks.",
                        created_ts=int(time.time()),
                    )
                )

        return insights


class SiloRiskDetector(BaseDetector):
    """Detect high-blast lobes with inactive primary authors."""

    def detect(self, conn: Connection) -> list[Insight]:
        insights: list[Insight] = []

        # Check if memories has author_stats (from Idea #09)
        tables = {r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        if "memories" not in tables:
            return insights

        # Find lobes with high blast radius (from health_snapshots)
        health = conn.execute(
            "SELECT avg_blast FROM health_snapshots ORDER BY build_ts DESC LIMIT 1"
        ).fetchone()
        if not health or health["avg_blast"] < 20:
            return insights

        # Find primary authors per lobe from memories
        rows = conn.execute(
            """
            SELECT lobe, author, COUNT(*) as cnt
            FROM memories
            WHERE lobe IS NOT NULL AND author IS NOT NULL
            GROUP BY lobe, author
            ORDER BY lobe, cnt DESC
            """
        ).fetchall()

        lobe_authors: dict[str, list[tuple[str, int]]] = {}
        for row in rows:
            lobe_authors.setdefault(row["lobe"], []).append((row["author"], row["cnt"]))

        # Check if primary author has been inactive > 60 days
        cutoff = int(time.time()) - 60 * 86400
        for lobe, authors in lobe_authors.items():
            if not authors:
                continue
            primary_author, _ = authors[0]
            last_activity = conn.execute(
                "SELECT MAX(created_ts) FROM memories WHERE lobe = ? AND author = ?",
                (lobe, primary_author),
            ).fetchone()
            if last_activity and last_activity[0] and last_activity[0] < cutoff:
                days = (int(time.time()) - last_activity[0]) // 86400
                insights.append(
                    Insight(
                        type="silo_risk",
                        title=f"Primary author {primary_author} inactive on {lobe}/ for {days} days — bus factor: 1",
                        body=f"{primary_author} has not authored memories in {lobe}/ since {days} days ago. This lobe has high blast radius; knowledge is concentrated.",
                        confidence=0.8,
                        affected_neurons=[],
                        affected_lobes=[lobe],
                        recommendation="Encourage knowledge sharing; pair programming; document key decisions.",
                        created_ts=int(time.time()),
                    )
                )

        return insights


class ArchPredictionDetector(BaseDetector):
    """Predict when blast radius will exceed arch rule thresholds."""

    def detect(self, conn: Connection) -> list[Insight]:
        insights: list[Insight] = []

        # Get recent blast radius trend
        rows = conn.execute(
            "SELECT build_ts, avg_blast FROM health_snapshots ORDER BY build_ts DESC LIMIT 5"
        ).fetchall()

        if len(rows) < 3:
            return insights

        # Linear projection
        times = [r["build_ts"] for r in rows]
        blasts = [r["avg_blast"] for r in rows]

        # Simple slope
        if times[0] != times[-1]:
            slope = (blasts[0] - blasts[-1]) / (times[0] - times[-1])  # per second
            if slope > 0:
                # Project to threshold 50
                current = blasts[0]
                if current < 50:
                    seconds_to_50 = (50 - current) / slope
                    if seconds_to_50 < 30 * 86400:  # within 30 days
                        builds_left = int(seconds_to_50 / 86400)  # ~1 build/day
                        insights.append(
                            Insight(
                                type="arch_prediction",
                                title=f"Blast radius trending toward rule threshold (50) — ~{builds_left} builds at current rate",
                                body=f"Avg blast radius: {current:.1f}, growing at {slope*86400:.2f}/build. Will exceed 50 in ~{builds_left} builds.",
                                confidence=min(slope * 1000, 0.9),
                                affected_neurons=[],
                                affected_lobes=[],
                                recommendation="Review new edges being added; enforce arch rules earlier in review pipeline.",
                                created_ts=int(time.time()),
                            )
                        )

        return insights


class MemoryConflictDetector(BaseDetector):
    """Detect contradicting memories on the same neuron."""

    def detect(self, conn: Connection) -> list[Insight]:
        insights: list[Insight] = []

        # Find neurons with multiple decision/warning memories that might conflict
        rows = conn.execute(
            """
            SELECT neuron_id, COUNT(*) as cnt
            FROM memories
            WHERE type IN ('decision', 'warning') AND neuron_id IS NOT NULL
            GROUP BY neuron_id
            HAVING cnt > 1
            """
        ).fetchall()

        for row in rows:
            neuron = row["neuron_id"]
            # Get the conflicting memories
            mems = conn.execute(
                "SELECT id, title, body, author, created_ts FROM memories WHERE neuron_id = ? AND type IN ('decision', 'warning') ORDER BY created_ts DESC LIMIT 5",
                (neuron,),
            ).fetchall()

            if len(mems) >= 2:
                # Simple heuristic: if titles contain opposite sentiment words
                titles = [m["title"].lower() for m in mems]
                conflicts = any("not" in t or "avoid" in t or "never" in t for t in titles) and any(
                    "use" in t or "adopt" in t or "always" in t for t in titles
                )
                if conflicts:
                    insights.append(
                        Insight(
                            type="memory_conflict",
                            title=f"Conflicting decisions about {neuron}",
                            body=f"Found {len(mems)} decisions/warnings for {neuron}. Latest: {mems[0]['title']} by {mems[0]['author']}. Previous: {mems[1]['title']} by {mems[1]['author']}.",
                            confidence=0.75,
                            affected_neurons=[neuron],
                            affected_lobes=[],
                            recommendation="Review the conflicting memories; consolidate or mark one as superseded.",
                            created_ts=int(time.time()),
                        )
                    )

        return insights


class CoverageRegressionDetector(BaseDetector):
    """Detect test surface regression (also handled in TrendAlertDetector but specific)."""

    def detect(self, conn: Connection) -> list[Insight]:
        # Handled by TrendAlertDetector; return empty to avoid duplicates
        return []


class AgentDriftDetector(BaseDetector):
    """Detect when an agent changes more neurons than impact predicted."""

    def detect(self, conn: Connection) -> list[Insight]:
        insights: list[Insight] = []

        tables = {r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        if "sessions" not in tables or "session_events" not in tables:
            return insights

        rows = conn.execute(
            """
            SELECT s.id, s.outcome, s.neurons_touched, s.blast_radius_before, s.blast_radius_after
            FROM sessions s
            WHERE s.outcome IN ('success', 'failed')
            ORDER BY s.started_at DESC
            LIMIT 20
            """
        ).fetchall()

        for row in rows:
            if row["neurons_touched"]:
                try:
                    touched = len(row["neurons_touched"].split(","))
                except (AttributeError, ValueError):
                    continue
                predicted = row["blast_radius_before"] or 0
                actual = row["blast_radius_after"] or 0
                if predicted > 0 and actual > predicted * 2:
                    insights.append(
                        Insight(
                            type="agent_drift",
                            title=f"Session {row['id'][:8]} changed {touched} neurons vs predicted {predicted}",
                            body=f"Agent session {row['id']} touched {touched} neurons but impact analysis predicted blast radius of {predicted}. Actual blast after: {actual}.",
                            confidence=0.85,
                            affected_neurons=[],
                            affected_lobes=[],
                            recommendation="Review session log; agent may have made unanticipated changes. Run cerebrofy_impact before future sessions.",
                            created_ts=int(time.time()),
                        )
                    )

        return insights


class ArchViolationPredictionDetector(BaseDetector):
    """Predict arch rule violations from edge patterns."""

    def detect(self, conn: Connection) -> list[Insight]:
        insights: list[Insight] = []

        # Check arch_rules table for forbidden patterns
        tables = {r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
        if "arch_rules" not in tables:
            return insights

        rules = conn.execute("SELECT id, pattern, severity FROM arch_rules WHERE enabled = 1").fetchall()
        for rule in rules:
            # Check how many edges match the forbidden pattern
            pattern = rule["pattern"]
            count = conn.execute(
                "SELECT COUNT(*) as cnt FROM edges WHERE rel_type = ?",
                (pattern,),
            ).fetchone()
            if count and count["cnt"] > 0:
                insights.append(
                    Insight(
                        type="arch_violation_prediction",
                        title=f"Arch rule '{rule['id']}' has {count['cnt']} violations — approaching threshold",
                        body=f"Found {count['cnt']} edges matching forbidden pattern '{pattern}'. Rule severity: {rule['severity']}.",
                        confidence=min(count["cnt"] / 20, 0.9),
                        affected_neurons=[],
                        affected_lobes=[],
                        recommendation="Review edges matching this pattern; refactor to comply with arch rule before merge.",
                        created_ts=int(time.time()),
                    )
                )

        return insights